import{_ as l,l as e,o as i,b as o,q as n,m as r,j as s}from"./chunks/framework.Tf23FRXt.js";const k=JSON.parse('{"title":"游戏背景介绍","description":"","frontmatter":{},"headers":[{"level":2,"title":"游戏世界观","slug":"游戏世界观","link":"#游戏世界观","children":[]},{"level":2,"title":"游戏版本","slug":"游戏版本","link":"#游戏版本","children":[]}],"relativePath":"before/world.htm.md","filePath":"before/world.md","lastUpdated":1791098838000}'),h={name:"before/world.htm.md"};function c(p,t,b,_,f,m){const d=e("IncludePage"),a=e("CollapseText");return i(),o("div",null,[t[0]||(t[0]=n('<h1 id="游戏背景介绍" tabindex="-1">游戏背景介绍</h1><p>FF14 是一个拥有宏伟世界观的游戏，背负着<strong>最终幻想</strong>这个响亮的名字，代表着最初与最终的幻想，讲述了玩家从一介冒险者成长为拯救世界英雄，以及这个世界中奋力拼搏着的人们的故事。</p><p>作为一款 MMORPG 游戏，FF14 拥有丰富多彩的玩法，喜爱战斗的玩家自不必说，不擅于战斗的玩家们也可以从生产、采集、换装、摄影、演奏、RP 等等各个方面找到自己的兴趣爱好，着实是可以生活在这个世界里的游戏。所有的玩法都可以在<a href="/">首页一览</a>中看到，不必要拘泥于满级或者强力装备，很多玩法并不要求你有满级的职业（<a href="/topic/relax.htm">休闲玩法介绍</a>），最强力的装备也会如过眼云烟（<a href="/advanced/bis.htm">毕业装介绍</a>），愿水晶指引你的道路。</p><h2 id="游戏世界观" tabindex="-1">游戏世界观</h2><p>FF14 的主要游戏世界是行星海德林，在海德林的<s>非洲</s>艾欧泽亚生活着信奉十二神的人民 (<a href="https://ff14.huijiwiki.com/wiki/%E5%8D%81%E4%BA%8C%E7%A5%9E" target="_blank" rel="noreferrer">十二神是什么</a>)，他们分散在三大城邦中居住 ——</p><ul><li>海之都 “利姆萨・罗敏萨”；</li><li>森之都 “格里达尼亚”；</li><li>沙之都 “乌尔达哈”。</li></ul><p>我们<s>跑腿</s>冒险者的故事就是从这 3 个城市之一开始的，根据你所选择的职业不同，会出生在这三城之一，之后这些主城也会成为玩家的聚集地（并没有什么新手村哦）。冒险者的一生是追逐命运和声望的一生。冒险者牺牲自己来追求潜藏的危险和光荣。只有最无畏的灵魂才能踏上无尽探索的旅途。官方制作了更详细的世界观背景故事介绍 ——<a href="http://ff.sdo.com/date/na/world/index.html" target="_blank" rel="noreferrer"> 点我查看</a>。<a href="https://ff14.huijiwiki.com/wiki/%E5%8E%86%E5%8F%B2" target="_blank" rel="noreferrer">灰机维基上记载有更详细的杂学、历史年表及剧情梗概（有剧透要注意！）</a>。</p><h2 id="游戏版本" tabindex="-1">游戏版本</h2><p>FF14 采用类似单机的本体 + DLC 发布模式，目前已经发布了 3.0~7.0 五个 DLC，等级上限是 100 级。如果是国际服玩家的话，每个 DLC 需要单独购买，高等级的 DLC 包含了低级的 DLC 内容；而国服玩家只要激活帐号（充值了点卡或者月卡），就可以直接玩到所有版本了。国际服相关规则请查看<a href="/basic/international.htm">国际服专题</a>。</p><div class="md-table"><table class="ui compact grey striped unstackable table"><thead><tr><th>版本</th><th>等级区间</th><th>简介</th></tr></thead><tbody><tr><td>2.0<br>重生之境</td><td>1~50</td><td>玩家创建角色后，主要活动舞台在上文提到的三个主城 —— 拉诺西亚、黑衣森林、萨纳兰地区及摩杜纳。<br>这个阶段中我们会接触这个世界的历史 —— 第七灵灾。</td></tr><tr><td>3.0<br>苍穹之禁城</td><td>50~60</td><td>冒险者前往伊修加德、阿巴拉提亚云海和龙堡，深入了解伊修加德的民众与龙族之间的龙诗战争，甚至接触到生活在云海的莫古一族，揭开古代亚拉戈文明神秘面纱的一角。</td></tr><tr><td>4.0<br>红莲之狂潮</td><td>60~70</td><td>冒险者前往黑衣森林东北方向基拉巴尼亚的阿拉米格，远东之国的黄金港，还有敖龙族的老家太阳神草原，以及水下的世界。<br>在这里会接触到帝国对周边国家的统治，和人民的意志。</td></tr><tr><td>5.0<br>暗影之逆焰</td><td>70~80</td><td>冒险者被召唤到第一世界，一边调查一边解决在那个世界发生的危机。<br>在前进的过程中反而揭开了 2.0~4.0 剧情中神秘反派和整个世界的真相，并为接下来的决战拉开了序幕。</td></tr><tr><td>6.0<br>晓月之终途</td><td>80~90</td><td>冒险者将迎来围绕着星球和生命的故事「海德林与佐迪亚克之章」的完结。<br>冒险者会穿越北洋的旧萨雷安、近东的拉札罕以及加雷马帝国，甚至是夜空中漂浮着的月球，<br>将被托付的思念转换为力量，拯救濒于终结的世界。</td></tr><tr><td>7.0<br>金曦之遗辉</td><td>90~100</td><td>结束拯救世界使命冒险者，踏上了新大陆，展开了新的旅程。</td></tr></tbody></table></div>',10)),r(a,{summary:"1.0 去哪了？"},{default:s(()=>[r(d,{file:"_includes/history/documentary.md"})]),_:1})])}const C=l(h,[["render",c]]);export{k as __pageData,C as default};
